19	const AuthCallback = () => {
20	  const navigateTo = useNavigateTo();
21	  const { currentUser, initialize, isInitialized } = useAuth();
22	  const [searchParams] = useSearchParams();
23	  const handledRef = useRef(false);
24	  const [state, setState] = useState<State>({
25	    loading: true,
26	    errorMessage: "",
27	  });
28	
29	  useEffect(() => {
30	    if (!isInitialized) {
31	      return;
32	    }
33	    if (handledRef.current) {
34	      return;
35	    }
36	    // Check for OAuth error response first (e.g., user denied access)
37	    const error = searchParams.get("error");
38	    const errorDescription = searchParams.get("error_description");
39	    const errorUri = searchParams.get("error_uri");
40	
41	    if (error) {
42	      // OAuth provider returned an error
43	      let errorMessage = `OAuth error: ${error}`;
44	      if (errorDescription) {
45	        errorMessage += `\n${decodeURIComponent(errorDescription)}`;
46	      }
47	      if (errorUri) {
48	        errorMessage += `\nMore info: ${errorUri}`;
49	      }
50	
51	      setState({
52	        loading: false,
53	        errorMessage,
54	      });
55	      return;
56	    }
57	
58	    const code = searchParams.get("code");
59	    const state = searchParams.get("state");
60	
61	    if (!code || !state) {
62	      setState({
63	        loading: false,
64	        errorMessage: "Failed to authorize. Missing authorization code or state parameter.",
65	      });
