71	    if (!validatedState) {
72	      setState({
73	        loading: false,
74	        errorMessage: "Failed to authorize. Invalid or expired state parameter. This may indicate a CSRF attack attempt.",
75	      });
76	      return;
77	    }
78	
79	    const { flowMode, identityProviderName, returnUrl, linkingUserName, codeVerifier } = validatedState;
80	    const redirectUri = absolutifyLink("/auth/callback");
81	    handledRef.current = true;
82	
