140	  if (state.loading) return null;
141	
142	  return (
143	    <div className="p-4 py-24 w-full h-full flex justify-center items-center">
144	      <div className="max-w-lg font-mono whitespace-pre-wrap opacity-80">{state.errorMessage}</div>
145	    </div>
146	  );
